// FirstFrame database schema (Drizzle ORM, PostgreSQL).
//
// Conventions:
// - Primary keys are UUIDs generated by Postgres.
// - Money is always stored in paise (1 rupee = 100 paise) as integers,
//   so payments never suffer floating-point rounding errors.
// - Timestamps are stored with time zone.
import { relations, sql } from 'drizzle-orm';
import {
  boolean,
  check,
  doublePrecision,
  index,
  integer,
  jsonb,
  pgEnum,
  pgTable,
  text,
  timestamp,
  uniqueIndex,
  uuid,
} from 'drizzle-orm/pg-core';

const id = () => uuid('id').primaryKey().defaultRandom();
const createdAt = () => timestamp('created_at', { withTimezone: true }).notNull().defaultNow();
const updatedAt = () =>
  timestamp('updated_at', { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date());

// ---------- Enums ----------

export const roleEnum = pgEnum('role', ['UPLOADER', 'CHANNEL', 'ADMIN']);
export const channelStatusEnum = pgEnum('channel_status', ['PENDING', 'APPROVED', 'REJECTED']);
export const mediaTypeEnum = pgEnum('media_type', ['VIDEO', 'PHOTO']);
export const mediaStatusEnum = pgEnum('media_status', [
  'PROCESSING', // uploaded, waiting for or inside the background worker
  'IN_REVIEW', // processed, waiting for an admin decision
  'APPROVED', // visible to news channels and purchasable
  'REJECTED', // rejected by an admin
  'FAILED', // processing failed (corrupt file, unsupported codec, ...)
  'REMOVED', // taken down (by the uploader, or after a valid report)
]);
export const categoryEnum = pgEnum('category', [
  'FIRE',
  'ACCIDENT',
  'FLOOD',
  'WEATHER',
  'PROTEST',
  'CRIME',
  'INFRASTRUCTURE',
  'OTHER',
]);
export const riskLevelEnum = pgEnum('risk_level', ['LOW', 'MEDIUM', 'HIGH']);
export const licenseTypeEnum = pgEnum('license_type', ['NON_EXCLUSIVE', 'EXCLUSIVE']);
export const orderStatusEnum = pgEnum('order_status', [
  'CREATED', // checkout started, waiting for payment (until expires_at)
  'PAID', // captured and the licence granted
  'FAILED', // the payment was declined (the buyer may still retry inside the same checkout)
  'EXPIRED', // nobody paid before expires_at; a payment arriving later is refunded
  'REFUND_PENDING', // money was captured but no licence can be granted: a refund job is running
  'REFUNDED', // the order's payment was refunded (by us, or in the Razorpay dashboard); licence revoked
  'REFUND_FAILED', // the refund job gave up: an admin must retry it
  'DISPUTED', // the buyer's bank opened a chargeback; licence revoked, uploader credit reversed
]);
export const ledgerTypeEnum = pgEnum('ledger_type', [
  'SALE_CREDIT', // uploader's share of a sale (+), spendable from available_at
  'SALE_REVERSAL', // the sale was refunded or charged back (-)
  'SALE_REINSTATEMENT', // a chargeback was won, the share comes back (+)
  'PAYOUT_DEBIT', // money paid out to the uploader (-)
  'PAYOUT_REVERSAL', // a rejected payout gives the money back (+)
  'ADJUSTMENT', // manual correction by an admin (+/-), always with a note
]);
export const refundStatusEnum = pgEnum('refund_status', ['PENDING', 'PROCESSED', 'FAILED']);
export const payoutStatusEnum = pgEnum('payout_status', ['REQUESTED', 'PAID', 'REJECTED']);
export const reportStatusEnum = pgEnum('report_status', ['OPEN', 'RESOLVED', 'DISMISSED']);

export const ROLES = roleEnum.enumValues;
export const CATEGORIES = categoryEnum.enumValues;
export const LICENSE_TYPES = licenseTypeEnum.enumValues;
export type Role = (typeof ROLES)[number];
export type Category = (typeof CATEGORIES)[number];
export type LicenseType = (typeof LICENSE_TYPES)[number];
export type MediaStatus = (typeof mediaStatusEnum.enumValues)[number];
export type RiskLevel = (typeof riskLevelEnum.enumValues)[number];

// ---------- Users ----------

export const users = pgTable('users', {
  id: id(),
  email: text('email').notNull().unique(),
  passwordHash: text('password_hash').notNull(),
  name: text('name').notNull(),
  role: roleEnum('role').notNull(),
  createdAt: createdAt(),
  updatedAt: updatedAt(),
});

export const uploaderProfiles = pgTable('uploader_profiles', {
  userId: uuid('user_id')
    .primaryKey()
    .references(() => users.id, { onDelete: 'cascade' }),
  upiId: text('upi_id'),
  /** When the UPI ID was last changed from a previous value; payouts wait for a cooling-off period after it. */
  upiChangedAt: timestamp('upi_changed_at', { withTimezone: true }),
  updatedAt: updatedAt(),
});

/** Audit trail of payout-destination changes (who, when, from where). Append-only by convention. */
export const payoutDetailChanges = pgTable(
  'payout_detail_changes',
  {
    id: id(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    oldUpiId: text('old_upi_id'),
    newUpiId: text('new_upi_id').notNull(),
    ip: text('ip'),
    userAgent: text('user_agent'),
    createdAt: createdAt(),
  },
  (t) => [index('payout_detail_changes_user_created_idx').on(t.userId, t.createdAt)],
);

export const channelProfiles = pgTable(
  'channel_profiles',
  {
    userId: uuid('user_id')
      .primaryKey()
      .references(() => users.id, { onDelete: 'cascade' }),
    organization: text('organization').notNull(),
    website: text('website'),
    status: channelStatusEnum('status').notNull().default('PENDING'),
    reviewNote: text('review_note'),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [index('channel_profiles_status_idx').on(t.status)],
);

// Refresh tokens are stored hashed (SHA-256). Every refresh rotates the token:
// the old row is revoked and points at its replacement, so reuse of a
// rotated token can be detected and the whole family revoked.
export const refreshTokens = pgTable(
  'refresh_tokens',
  {
    id: id(),
    userId: uuid('user_id')
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    tokenHash: text('token_hash').notNull().unique(),
    expiresAt: timestamp('expires_at', { withTimezone: true }).notNull(),
    revokedAt: timestamp('revoked_at', { withTimezone: true }),
    replacedById: uuid('replaced_by_id'),
    createdAt: createdAt(),
  },
  (t) => [index('refresh_tokens_user_idx').on(t.userId)],
);

// ---------- Incidents and media ----------

// An incident groups uploads that happened close together in place and time
// (same or neighbouring geohash cell, inside a time window).
export const incidents = pgTable(
  'incidents',
  {
    id: id(),
    title: text('title').notNull(),
    category: categoryEnum('category').notNull(),
    geohash: text('geohash').notNull(), // precision 6, about 1.2 km x 0.6 km
    latitude: doublePrecision('latitude').notNull(),
    longitude: doublePrecision('longitude').notNull(),
    locationName: text('location_name'),
    firstSeenAt: timestamp('first_seen_at', { withTimezone: true }).notNull(),
    lastSeenAt: timestamp('last_seen_at', { withTimezone: true }).notNull(),
    mediaCount: integer('media_count').notNull().default(0), // approved media only
    uploaderCount: integer('uploader_count').notNull().default(0), // distinct uploaders of approved media
    viewCount: integer('view_count').notNull().default(0),
    trendScore: doublePrecision('trend_score').notNull().default(0),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index('incidents_geohash_last_seen_idx').on(t.geohash, t.lastSeenAt),
    index('incidents_trend_idx').on(t.trendScore),
    index('incidents_last_seen_idx').on(t.lastSeenAt),
  ],
);

export const media = pgTable(
  'media',
  {
    id: id(),
    uploaderId: uuid('uploader_id')
      .notNull()
      .references(() => users.id),
    incidentId: uuid('incident_id').references(() => incidents.id),
    type: mediaTypeEnum('type').notNull(),
    status: mediaStatusEnum('status').notNull().default('PROCESSING'),
    title: text('title').notNull(),
    description: text('description'),
    category: categoryEnum('category').notNull(),
    latitude: doublePrecision('latitude').notNull(),
    longitude: doublePrecision('longitude').notNull(),
    geohash: text('geohash').notNull(),
    locationName: text('location_name'),
    capturedAt: timestamp('captured_at', { withTimezone: true }).notNull(),

    // Original file: private, never shown before purchase.
    originalKey: text('original_key').notNull(),
    originalName: text('original_name').notNull(),
    mimeType: text('mime_type').notNull(),
    sizeBytes: integer('size_bytes').notNull(),
    checksum: text('checksum').notNull(), // sha256 of the original file

    // Filled in by the processing worker.
    durationSec: doublePrecision('duration_sec'),
    width: integer('width'),
    height: integer('height'),
    previewKey: text('preview_key'), // storage prefix of the HLS folder (video) or key of the preview JPEG (photo)
    thumbKey: text('thumb_key'), // storage key of the watermarked thumbnail
    hlsKeyHex: text('hls_key_hex'), // AES-128 key of the encrypted HLS preview (hex)

    // Prices in paise.
    priceNonExclusive: integer('price_non_exclusive').notNull(),
    priceExclusive: integer('price_exclusive').notNull(),
    exclusiveSold: boolean('exclusive_sold').notNull().default(false),

    processingError: text('processing_error'),
    reviewNote: text('review_note'),
    reviewedAt: timestamp('reviewed_at', { withTimezone: true }),
    viewCount: integer('view_count').notNull().default(0),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    index('media_status_created_idx').on(t.status, t.createdAt),
    index('media_uploader_created_idx').on(t.uploaderId, t.createdAt),
    index('media_incident_idx').on(t.incidentId),
    index('media_geohash_idx').on(t.geohash),
    index('media_checksum_idx').on(t.checksum),
  ],
);

// Evidence collected about an upload. These are signals, never a verdict:
// a human admin makes the final decision.
export const verifications = pgTable('verifications', {
  mediaId: uuid('media_id')
    .primaryKey()
    .references(() => media.id, { onDelete: 'cascade' }),
  aiScore: doublePrecision('ai_score'), // 0..1 probability of AI generation, null = detector unavailable
  aiModel: text('ai_model'),
  framesScored: integer('frames_scored').notNull().default(0),
  c2paStatus: text('c2pa_status').notNull(), // valid | invalid | absent | error | unsupported
  c2paIssuer: text('c2pa_issuer'),
  metadata: jsonb('metadata').$type<Record<string, unknown>>().notNull(),
  phashes: text('phashes')
    .array()
    .notNull()
    .default(sql`'{}'::text[]`),
  duplicateOfId: uuid('duplicate_of_id'),
  signals: jsonb('signals').$type<VerificationSignal[]>().notNull(),
  riskLevel: riskLevelEnum('risk_level').notNull(),
  createdAt: createdAt(),
});

export interface VerificationSignal {
  code: string; // e.g. AI_SCORE_HIGH, NO_METADATA, C2PA_VALID, DUPLICATE
  level: 'info' | 'warning' | 'danger' | 'positive';
  message: string;
}

// ---------- Money ----------

export const orders = pgTable(
  'orders',
  {
    id: id(),
    buyerId: uuid('buyer_id')
      .notNull()
      .references(() => users.id),
    mediaId: uuid('media_id')
      .notNull()
      .references(() => media.id),
    licenseType: licenseTypeEnum('license_type').notNull(),
    amount: integer('amount').notNull(), // paise, charged to the buyer
    platformFee: integer('platform_fee').notNull(), // paise, kept by the platform
    uploaderShare: integer('uploader_share').notNull(), // paise, credited to the uploader
    currency: text('currency').notNull().default('INR'),
    status: orderStatusEnum('status').notNull().default('CREATED'),
    provider: text('provider').notNull(), // razorpay | mock
    providerOrderId: text('provider_order_id').notNull().unique(),
    providerPaymentId: text('provider_payment_id').unique(),
    downloadCount: integer('download_count').notNull().default(0),
    /** Why the order is not (or no longer) PAID, shown to the buyer, e.g. "licence sold meanwhile". */
    statusReason: text('status_reason'),
    createdAt: createdAt(),
    /** An unpaid checkout stops being payable at this moment (the quoted price is honoured until then). */
    expiresAt: timestamp('expires_at', { withTimezone: true })
      .notNull()
      .default(sql`now() + interval '30 minutes'`),
    paidAt: timestamp('paid_at', { withTimezone: true }),
    refundedAt: timestamp('refunded_at', { withTimezone: true }),
    disputedAt: timestamp('disputed_at', { withTimezone: true }),
  },
  (t) => [
    index('orders_buyer_created_idx').on(t.buyerId, t.createdAt),
    index('orders_media_idx').on(t.mediaId),
    index('orders_status_expires_idx').on(t.status, t.expiresAt),
    // Backstops for the licence rules in markPaid: even a buggy future change cannot
    // sell an exclusive licence twice, or sell one channel the same media twice.
    uniqueIndex('orders_one_paid_exclusive_per_media_idx')
      .on(t.mediaId)
      .where(sql`${t.status} = 'PAID' and ${t.licenseType} = 'EXCLUSIVE'`),
    uniqueIndex('orders_one_paid_per_buyer_media_idx')
      .on(t.buyerId, t.mediaId)
      .where(sql`${t.status} = 'PAID'`),
    check('orders_amount_positive', sql`${t.amount} > 0`),
    check(
      'orders_split_valid',
      sql`${t.platformFee} >= 0 and ${t.uploaderShare} >= 0 and ${t.platformFee} + ${t.uploaderShare} = ${t.amount}`,
    ),
    check('orders_currency_inr', sql`${t.currency} = 'INR'`),
    check('orders_download_count_non_negative', sql`${t.downloadCount} >= 0`),
    // Every state that means "money was captured" must say which payment it was.
    // (::text, so the check does not depend on enum values added in the same migration.)
    check(
      'orders_captured_has_payment',
      sql`${t.status}::text not in ('PAID', 'REFUND_PENDING', 'REFUNDED', 'REFUND_FAILED', 'DISPUTED') or ${t.providerPaymentId} is not null`,
    ),
  ],
);

/**
 * Refunds we issue through the payment provider. One row per captured payment that
 * must be returned (the unique provider_payment_id makes "refund this payment" idempotent),
 * processed by the BullMQ job `refund` (job id = payment id).
 */
export const refunds = pgTable(
  'refunds',
  {
    id: id(),
    orderId: uuid('order_id')
      .notNull()
      .references(() => orders.id),
    provider: text('provider').notNull(), // razorpay | mock
    providerPaymentId: text('provider_payment_id').notNull().unique(),
    amount: integer('amount').notNull(), // paise
    reason: text('reason').notNull(),
    status: refundStatusEnum('status').notNull().default('PENDING'),
    providerRefundId: text('provider_refund_id').unique(),
    attempts: integer('attempts').notNull().default(0),
    lastError: text('last_error'),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
    processedAt: timestamp('processed_at', { withTimezone: true }),
  },
  (t) => [
    index('refunds_status_created_idx').on(t.status, t.createdAt),
    index('refunds_order_idx').on(t.orderId),
    check('refunds_amount_positive', sql`${t.amount} > 0`),
    check('refunds_attempts_non_negative', sql`${t.attempts} >= 0`),
  ],
);

export const payouts = pgTable(
  'payouts',
  {
    id: id(),
    uploaderId: uuid('uploader_id')
      .notNull()
      .references(() => users.id),
    amount: integer('amount').notNull(), // paise
    upiId: text('upi_id').notNull(),
    status: payoutStatusEnum('status').notNull().default('REQUESTED'),
    reference: text('reference'), // bank/UPI transaction reference once paid
    note: text('note'),
    createdAt: createdAt(),
    processedAt: timestamp('processed_at', { withTimezone: true }),
  },
  (t) => [
    index('payouts_uploader_created_idx').on(t.uploaderId, t.createdAt),
    index('payouts_status_idx').on(t.status),
    check('payouts_amount_positive', sql`${t.amount} > 0`),
  ],
);

// Append-only ledger of uploader money. Balance = SUM(amount);
// available balance = SUM(amount) of rows whose available_at has passed.
// Rows are never updated or deleted (a trigger enforces it, see migration 0001);
// corrections are new ADJUSTMENT rows.
export const ledgerEntries = pgTable(
  'ledger_entries',
  {
    id: id(),
    uploaderId: uuid('uploader_id')
      .notNull()
      .references(() => users.id),
    type: ledgerTypeEnum('type').notNull(),
    amount: integer('amount').notNull(), // paise, positive = credit, negative = debit
    orderId: uuid('order_id').references(() => orders.id),
    payoutId: uuid('payout_id').references(() => payouts.id),
    note: text('note'),
    /** The admin who wrote an ADJUSTMENT (null for rows written by the system). */
    createdBy: uuid('created_by').references(() => users.id),
    /** When this row starts counting towards the withdrawable balance (sale credits are held). */
    availableAt: timestamp('available_at', { withTimezone: true }).notNull().defaultNow(),
    createdAt: createdAt(),
  },
  (t) => [
    index('ledger_uploader_created_idx').on(t.uploaderId, t.createdAt),
    index('ledger_uploader_available_idx').on(t.uploaderId, t.availableAt),
    // One sale credit per order: makes crediting idempotent at the database level.
    uniqueIndex('ledger_one_credit_per_order_idx')
      .on(t.orderId)
      .where(sql`${t.type} = 'SALE_CREDIT'`),
    // At most one row of each type per order (credit, reversal, reinstatement) and per
    // payout (debit, reversal): double-crediting or double-reversing is impossible.
    uniqueIndex('ledger_one_type_per_order_idx')
      .on(t.orderId, t.type)
      .where(sql`${t.orderId} is not null`),
    uniqueIndex('ledger_one_type_per_payout_idx')
      .on(t.payoutId, t.type)
      .where(sql`${t.payoutId} is not null`),
    check('ledger_amount_non_zero', sql`${t.amount} <> 0`),
    check(
      'ledger_amount_sign_matches_type',
      sql`(${t.type}::text in ('SALE_CREDIT', 'SALE_REINSTATEMENT', 'PAYOUT_REVERSAL') and ${t.amount} > 0)
        or (${t.type}::text in ('SALE_REVERSAL', 'PAYOUT_DEBIT') and ${t.amount} < 0)
        or ${t.type}::text = 'ADJUSTMENT'`,
    ),
    check(
      'ledger_references_match_type',
      sql`(${t.type}::text not in ('SALE_CREDIT', 'SALE_REVERSAL', 'SALE_REINSTATEMENT') or ${t.orderId} is not null)
        and (${t.type}::text not in ('PAYOUT_DEBIT', 'PAYOUT_REVERSAL') or ${t.payoutId} is not null)`,
    ),
    check(
      'ledger_adjustment_has_note',
      sql`${t.type}::text <> 'ADJUSTMENT' or length(trim(coalesce(${t.note}, ''))) >= 3`,
    ),
  ],
);

// Processed payment webhook event ids, so a retried webhook is never applied twice.
export const webhookEvents = pgTable('webhook_events', {
  id: text('id').primaryKey(), // provider event id
  provider: text('provider').notNull(),
  type: text('type').notNull(),
  // SHA-256 of the signed raw body. The event-id header is not covered by the signature,
  // so a replayed body under a new event id is caught by this unique column instead.
  payloadHash: text('payload_hash').unique(),
  receivedAt: timestamp('received_at', { withTimezone: true }).notNull().defaultNow(),
});

// Grievance / takedown requests (an intermediary must handle these under the IT Rules).
export const reports = pgTable(
  'reports',
  {
    id: id(),
    mediaId: uuid('media_id').references(() => media.id),
    reporterEmail: text('reporter_email').notNull(),
    reason: text('reason').notNull(),
    details: text('details'),
    status: reportStatusEnum('status').notNull().default('OPEN'),
    resolution: text('resolution'),
    createdAt: createdAt(),
    resolvedAt: timestamp('resolved_at', { withTimezone: true }),
  },
  (t) => [index('reports_status_created_idx').on(t.status, t.createdAt)],
);

// ---------- Relations (used by Drizzle's relational query API) ----------

export const usersRelations = relations(users, ({ one, many }) => ({
  uploader: one(uploaderProfiles),
  channel: one(channelProfiles),
  media: many(media),
  orders: many(orders),
}));

export const uploaderProfilesRelations = relations(uploaderProfiles, ({ one }) => ({
  user: one(users, { fields: [uploaderProfiles.userId], references: [users.id] }),
}));

export const channelProfilesRelations = relations(channelProfiles, ({ one }) => ({
  user: one(users, { fields: [channelProfiles.userId], references: [users.id] }),
}));

export const incidentsRelations = relations(incidents, ({ many }) => ({
  media: many(media),
}));

export const mediaRelations = relations(media, ({ one, many }) => ({
  uploader: one(users, { fields: [media.uploaderId], references: [users.id] }),
  incident: one(incidents, { fields: [media.incidentId], references: [incidents.id] }),
  verification: one(verifications),
  orders: many(orders),
}));

export const verificationsRelations = relations(verifications, ({ one }) => ({
  media: one(media, { fields: [verifications.mediaId], references: [media.id] }),
}));

export const ordersRelations = relations(orders, ({ one, many }) => ({
  buyer: one(users, { fields: [orders.buyerId], references: [users.id] }),
  media: one(media, { fields: [orders.mediaId], references: [media.id] }),
  refunds: many(refunds),
}));

export const refundsRelations = relations(refunds, ({ one }) => ({
  order: one(orders, { fields: [refunds.orderId], references: [orders.id] }),
}));

export const payoutsRelations = relations(payouts, ({ one }) => ({
  uploader: one(users, { fields: [payouts.uploaderId], references: [users.id] }),
}));

export const ledgerEntriesRelations = relations(ledgerEntries, ({ one }) => ({
  uploader: one(users, { fields: [ledgerEntries.uploaderId], references: [users.id] }),
  order: one(orders, { fields: [ledgerEntries.orderId], references: [orders.id] }),
  payout: one(payouts, { fields: [ledgerEntries.payoutId], references: [payouts.id] }),
}));

export const reportsRelations = relations(reports, ({ one }) => ({
  media: one(media, { fields: [reports.mediaId], references: [media.id] }),
}));
